import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/28-Are-war-robots-reliable.html","title":"29-当人工智能拿起武器，我们该担心什么？","lang":"zh-CN","frontmatter":{"title":"29-当人工智能拿起武器，我们该担心什么？","icon":"read","date":"2025-04-25T18:56:55.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1745590927000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":8,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"e47cd8fe150fc18143cef549f6f42e4978addb2e","time":1745590927000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改名称"},{"hash":"ffb3b4ebc4a49ba2207dd270ebdf26b3cf9175f9","time":1745579630000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"aa01ecbf186ea5a5667b2605e6da98f6ab3b82cb","time":1745579315000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.25,"words":2474},"filePathRelative":"column/Programmingthinking/28-Are-war-robots-reliable.md"}`),a={name:`28-Are-war-robots-reliable.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>今天我要给你说的是战争机器人。在正式开始今天的课程之前，我想请你玩个游戏，指挥一场战斗。</p><p>背景是这样的，有一个坏蛋从监狱里逃了出来，躲进了一座房子里。你可以动用各种先进的人工智能技术抓住他。不过注意了，这座房子里还住着平民，<strong>抓住坏蛋的时候千万不能伤了好人</strong>。你要怎么处理呢？你可以暂停先思考一下。</p><figure><img src="/assets/7221fc98011fc9ff5ff3750648328740-D8S_oId6.jpg" alt="无人机" tabindex="0" loading="lazy"><figcaption>无人机</figcaption></figure><p>下面，我来说一个办法。如果直接就派出人类士兵，他跟坏蛋搏斗的时候会受伤，不太稳妥。所以我啊，会派<strong>无人机</strong>进入这座房子。</p><p>另外，我会在这个无人机上装上<strong>人脸识别技术</strong>，可以扫描房间里的人脸。如果被扫描的目标是好人，无人机就会避开他们，如果发现了坏人，无人机就会计算出一条最好的路线冲过去，用无人机上的电击武器把坏蛋给电晕了。这时候再派出士兵，就可以轻松抓住敌人了。</p><p>当然了，你想的方法可能和我想的不一样，但你会发现，有了<strong>人工智能技术</strong>的帮助，想抓住坏人简直是轻而易举。</p><p>听到这，你是不是觉得，这人工智能技术太方便了，能消灭坏人，又不会误伤好人，要是真把这项技术用在战场上，说不定能减少很多无辜的伤亡呢。</p><figure><img src="/assets/c7aa11f249f576af36def654d62f74b3-CGTnsW3U.jpg" alt="大狗机器人" tabindex="0" loading="lazy"><figcaption>大狗机器人</figcaption></figure><p>你还别说，人工智能技术已经出现在战场上了。比方说，<strong>在2010年</strong>，在<strong>阿富汗</strong>的<strong>美军</strong>里多了一项新装备，名叫“<strong>大狗机器人</strong>”。</p><p>这个机器人，是美国一家叫“<strong>波士顿动力</strong>”的公司研制出来的，它长着4条腿，能和狗狗一样用腿走路跑步，如果被人不小心踢了一脚或是被撞了一下，它可能会踉跄几步，但很快就能找回平衡，重新站好，简直就像是一条宠物狗。</p><p>你可能会问了，这是不是宠物机器人呀？用来逗士兵开心的？当然不是了，它来到阿富汗战场，是要帮美军解决一个大问题的。</p><p>什么问题呢？就是美军在阿富汗战场上的<strong>装备运输</strong>问题。一般情况下，军队是靠汽车来运送装备。但是阿富汗这个地方，山地特别多，汽车根本就没法开。</p><p>怎么办呢？最开始的时候，美国军队就训练<strong>骡子</strong>来运送货物。于是在战场上，你可以看到一队装备精良的美军士兵，牵着骡子在行军。</p><figure><img src="/assets/bdcbfd877123ea197e3ba6f2d2506b92-CxYKTOKH.jpg" alt="运送货物的骡子" tabindex="0" loading="lazy"><figcaption>运送货物的骡子</figcaption></figure><p>而且，万一有敌人发起突袭，枪声一响，骡子可能被吓得四处乱跑，士兵们打完仗还要漫山遍野去找骡子，想想这个画面也是很滑稽。</p><p>美国国防部就想：“我们的精锐部队打仗还要带骡子，太不威风了。必须找人开发一款机器人，代替骡子，这样才够酷。”于是，长着四条腿的大狗机器人就诞生了。</p><p><strong>在2010年</strong>，大狗机器人被正式送到战场上参加实地测试了。要说这大狗机器人，它确实很方便。它可以驮着<strong>三四百斤</strong>的装备跟着士兵跑来跑去。而且它还有自动跟随系统。万一遭到了突袭，它也可以老老实实跟在美军士兵身后，不用担心它会被吓跑。万一真走丢了，士兵还可以通过遥控系统让它自己回到基地，这比骡子好用多了。</p><p>不过，用着用着，士兵们发现，大狗机器人也有些毛病。比如，大狗机器人实在是太吵了，当然了，它吵不是因为它乱叫，而是<strong>发动机的噪声</strong>太大了。有士兵说，隔着好几百米都能听见它的噪音。带着这样的家伙，绝对不可能搞什么偷袭。</p><p>还有，万一大狗机器人出了故障，普通士兵也没法修理它。想来想去，美军还是选择了用<strong>骡子</strong>。当然了，虽然不能做运输装备，但有人认为，大狗机器人可以当作战兵器。给它装上武器，就可以上前线杀敌了。</p><p>你还别说，还真有国家这么干了。比如俄罗斯，他们也造了自己的大狗机器人，在上面装上了机枪和火箭炮，士兵们不用冲上战场，躲在后方遥控这些武器，就可以消灭敌人了。</p><p>注意啊，这里面虽然装着武器的是大狗机器人，但最终决定开枪的是遥控器那头的<strong>人类</strong>。</p><p>那你可能会想了，如果给大狗加上<strong>面部识别系统</strong>，让它识别出敌人自动开枪，岂不是连遥控人员都省了？把大狗机器人往战场上一扔，就可以坐等战斗结束了，是不是很省事？</p><figure><img src="/assets/f23640ca081ecd5adbd39a7b295c93ef-Cn82bern.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>在这件事情上，很多科学家不同意，因为它太危险了。</p><p><strong>在2017年</strong>，一个科学家团队在网上公布了一段视频。说的是，恐怖分子掌握了<strong>AI技术</strong>，给无人机上面装了人脸识别功能，这种人脸识别技术很厉害，就算你戴上口罩，捂着半边脸都没有用。另外，它们在这种无人机上绑了炸药，一旦识别出了人脸，就冲过去引爆炸药，把人给炸死。听起来是不是非常可怕？</p><p>不过你不用担心，这个视频是科学家虚构出来的，目的就是为了引起大家对<strong>AI武器</strong>的重视。因为视频虽然是假的，但里面的技术却是存在的，正规的军队会用它来消灭坏人。</p><p>可既然是程序，那就有<strong>被黑客入侵</strong>的风险。如果黑客把好人的信息传输给机器人，机器人就可能大开杀戒。</p><p>而且，随着AI技术越来越发达，制造这样一台战争机器人会越来越简单。这样的技术落入坏人手里，那好人岂不是要遭殃了？</p><p>所以，在2017年的时候，很多科学家一起签署了一份公开信。<strong>反对把AI技术应用到战争中</strong>，你熟悉的<strong>埃隆·马斯克</strong>、<strong>霍金</strong>，都在这份公开信上签了名。后来，越来越多的科学家也加入到了他们的阵营中。</p><figure><img src="/assets/d3c60716565c8e22710f1c3c1b31dbb4-BC_KAaXE.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>可问题来了，这AI技术既可以用来消灭坏人，也可能威胁好人的安全，你说这AI技术还要不要继续发展呢？</p><p>说到这，我就要教你一个思考问题的方法，叫<strong>做辩证思维</strong>。在生活中，我们特别喜欢说一件事好或者不好。</p><p>但其实，很多事情都有<strong>两面性</strong>，就是既有好的一面也有坏的一面，我们做判断的时候，不能太过绝对。</p><p>就比如咱们前面说的大狗机器人吧，你要是给他装上人脸识别系统和机枪，那它就可怕的杀人机器。但要是给大狗装上医疗包和食物，它就可以完成各种各样的救援任务。</p><p>用辩证的思维去看问题，你就会比别人看得<strong>更全面</strong>。这种思考方式，你以后在历史课上也会经常用到。在分析一个历史事件的时候，不要简单地说好或者不好，试试能不能从不同的角度去分析它，得出更加可靠的结论。</p><figure><img src="/assets/707e77e8924bdc1016c069af5a6ec25d--2qoF1n3.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>那咱们说回人工智能技术，现在科学家们提倡要加快研究人工智能技术，并不是因为他们没有看到人工智能技术的问题。他们用<strong>辩证思维</strong>分析之后，认为人工智能给人类带来的<strong>好处是多于坏处</strong>的。而且，我们也有足够的时间来解决<strong>人工智能滥用</strong>这件事。所以，现在应当继续发展人工智能技术。</p><p>那咱们在前面提到一件事，人工智能兵器可能会被黑客入侵。在电影里，也经常会看到酷酷的黑客。你是不是很好奇，黑客到底是什么样的存在呢？我下集就给你说说黑客的事，我们下集见。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,42)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};